('analytics','{"enabled":true,"sampleRate":1,"trackPageviews":true,"trackClicks":true,"trackPerformance":true,"trackErrors":true,"trackApi":true,"maskInputs":true,"respectDnt":false,"anonymizeIp":false,"blacklistPaths":[],"errorIgnorePatterns":[],"retentionDays":180,"errorRetentionDays":90,"sessionTimeoutMinutes":30,"trackReplay":false,"replaySessionSampleRate":0,"replayOnError":true,"replayMaskAllText":false,"replayBlockSelector":"","replayRetentionDays":30,"replayStorageQuotaMb":4096}'::jsonb,'313b5d82ac54b008e0d8204b51327e6e4c7e53164b2d984f8c710cf8e6ee0cd5','{"$schema":"https://json-schema.org/draft/2020-12/schema","$ref":"#/$defs/Settings.Analytics","$defs":{"Settings.Analytics":{"type":"object","properties":{"enabled":{"default":true,"title":"启用采集","description":"关闭后不再采集新的行为、性能和错误数据","type":"boolean"},"sampleRate":{"default":1,"title":"采样率","description":"行为事件采集比例，0%–100%","type":"number","minimum":0,"maximum":1},"trackPageviews":{"default":true,"title":"页面浏览","type":"boolean"},"trackClicks":{"default":true,"title":"点击行为","type":"boolean"},"trackPerformance":{"default":true,"title":"性能指标","type":"boolean"},"trackErrors":{"default":true,"title":"错误采集","type":"boolean"},"trackApi":{"default":true,"title":"API 请求","type":"boolean"},"maskInputs":{"default":true,"title":"脱敏输入内容","type":"boolean"},"respectDnt":{"default":false,"title":"尊重 DNT","type":"boolean"},"anonymizeIp":{"default":false,"title":"IP 匿名化","description":"开启后仅存储网段，地理解析不受影响","type":"boolean"},"blacklistPaths":{"default":[],"title":"黑名单路径","type":"array","items":{"type":"string","maxLength":256}},"errorIgnorePatterns":{"default":[],"title":"错误忽略规则（正则）","description":"命中错误消息的前端错误不会上报","maxItems":50,"type":"array","items":{"type":"string","minLength":1,"maxLength":500}},"retentionDays":{"default":180,"title":"事件保留天数","type":"integer","minimum":1,"maximum":3650},"errorRetentionDays":{"default":90,"title":"错误保留天数","type":"integer","minimum":1,"maximum":3650},"sessionTimeoutMinutes":{"default":30,"title":"