DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM system_settings s LEFT JOIN settings_revision_definitions_0006 d ON d.module=s.module WHERE d.module IS NULL) THEN
    RAISE EXCEPTION 'Unknown settings module: refusing to discard current configuration';
  END IF;
END $$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION pg_temp.merge_settings_0006(base jsonb, overrides jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE result jsonb := base; pair record;
BEGIN
 FOR pair IN SELECT key, value FROM jsonb_each(overrides) LOOP
  IF jsonb_typeof(pair.value)='object' AND jsonb_typeof(result->pair.key)='object' THEN
   result := jsonb_set(result, ARRAY[pair.key], pg_temp.merge_settings_0006(result->pair.key,pair.value));
  ELSE result := jsonb_set(result, ARRAY[pair.key],pair.value); END IF;
 END LOOP;
 RETURN result;
END $$;
--> statement-breakpoint
INSERT INTO system_settings_revisions(settings_id,version,action,overrides,inherited,effective,inherited_version,definition_hash,definition,changed_paths,note,actor_id,actor_name,created_at)
SELECT s.id,s.version,'initial',s.data,
       CASE WHEN s.tenant_id IS NULL THEN d.defaults ELSE pg_temp.merge_settings_0006(d.defaults,coalesce(p.data,'{}'::jsonb)) END,
       pg_temp.merge_settings_0006(CASE WHEN s.tenant_id IS NULL THEN d.defaults ELSE pg_temp.merge_settings_0006(d.defaults,coalesce(p.data,'{}'::jsonb)) END,s.data),
       CASE WHEN s.tenant_id IS NULL THEN 0 ELSE coalesce(p.version,0) END,
       d.hash,d.definition,
       coalesce((SELECT jsonb_agg(path) FROM jsonb_array_elements_text(d.paths) AS path WHERE s.data #> string_to_array(path,'.') IS NOT NULL),'[]'::jsonb),
       '初始化当前配置版本',s.updated_by,u.username,s.updated_at
FROM system_settings s
JOIN settings_revision_definitions_0006 d ON d.module=s.module
LEFT JOIN system_settings p ON p.module=s.module AND p.tenant_id IS NULL
LEFT JOIN users u ON u.id=s.updated_by;
--> statement-breakpoint
UPDATE system_settings s SET current_revision_id=r.id FROM system_settings_revisions r WHERE r.settings_id=s.id;
--> statement-breakpoint
ALTER TABLE "system_settings" DROP COLUMN "data";--> statement-breakpoint
ALTER TABLE "system_settings" DROP COLUMN "version";
--> statement-breakpoint
CREATE OR REPLACE FUNCTION protect_settings_revision() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='UPDATE' OR EXISTS(SELECT 1 FROM system_settings WHERE id=OLD.settings_id) THEN
   RAISE EXCEPTION 'Settings revisions are immutable' USING ERRCODE='55000';
 END IF;
 RETURN OLD;
END $$;
--> statement-breakpoint
CREATE TRIGGER system_settings_revisions_immutable BEFORE UPDATE OR DELETE ON system_settings_revisions
FOR EACH ROW EXECUTE FUNCTION protect_settings_revision();
